final class Pq {
    private var a: [Job] = []            // reserve up front
    func push(_ j: Job) { a.append(j); siftUp(from: a.count - 1) }
    func pop() -> Job? { guard !a.isEmpty else { return nil }
        let top = a[0]; a[0] = a.removeLast(); siftDown(from: 0); return top }
